function init(){let e=localStorage.getItem("theme")||"light";e&&updateTheme(e),fetch("../json/promo.json").then(e=>e.json()).then(e=>{updateNumberStudent(e.apprenants),updateInformations(e)})}function updateTheme(e){document.documentElement.setAttribute("data-bs-theme",e)}function updateNumberStudent(e){let t=document.getElementById("numberStudent");t.innerText+=` ${e.length.toString()}`}function updateInformations(e){document.querySelector("strong[debutFormation]").innerText=e.debutFormation,document.querySelector("strong[finFormation]").innerText=e.finFormation,document.querySelector("div[description]").innerText=e.descriptionFormation,document.querySelector("h1[nomPromo]").innerText=e.nomPromo}window.onload=init;